def _decode_frame(encoded: str) -> Matrix:
    rows = encoded.split("/")
    if len(rows) != DRAWABLE_CELLS:
        raise ValueError(f"animation frame has {len(rows)} rows, expected {DRAWABLE_CELLS}")
    if any(len(row) != DRAWABLE_CELLS for row in rows):
        raise ValueError("animation frame has a row outside the 15-cell drawable width")
    if set("".join(rows)) - ({"."} | set(PALETTE)):
        raise ValueError("animation frame uses an unknown weather palette symbol")
    return tuple(row + "." for row in rows) + ("." * MATRIX_CELLS,)


WEATHER_ANIMATION_FRAMES: Final[Mapping[str, tuple[Matrix, ...]]] = {
    family: tuple(_decode_frame(encoded) for encoded in sequence)
    for family, sequence in _ENCODED_FRAMES.items()
}
WEATHER_ANIMATION_FAMILIES: Final[tuple[str, ...]] = tuple(
    family for family in WEATHER_SPRITES if family != "unknown"
)


def animation_resource_name(family: str, phase: int) -> str:
    """Return the stable Android resource name for one promoted frame."""

    if family not in WEATHER_ANIMATION_FRAMES:
        raise ValueError(f"weather family is not animated: {family!r}")
    if not 0 <= phase < FRAME_COUNT:
        raise ValueError(f"weather phase is outside 0..{FRAME_COUNT - 1}: {phase}")
    return f"raster_weather_anim_{family}_{phase:02d}"


def _frameset_hash(frames: Mapping[str, Sequence[Matrix]]) -> str:
    digest = hashlib.sha256()
    for family, sequence in frames.items():
        digest.update(family.encode())
        digest.update(b"\0")
        for matrix in sequence:
            digest.update("\n".join(matrix).encode())
            digest.update(b"\0")
    return digest.hexdigest()


def validate_weather_animation() -> None:
    """Enforce the promoted pixel, palette, gutter, and rest-frame contract."""

    if tuple(WEATHER_ANIMATION_FRAMES) != WEATHER_ANIMATION_FAMILIES:
        raise ValueError("animated weather family order drifted from WEATHER_SPRITES")
    for family, sequence in WEATHER_ANIMATION_FRAMES.items():
        if len(sequence) != FRAME_COUNT:
            raise ValueError(f"{family}: expected {FRAME_COUNT} animation frames")
        if sequence[0] != WEATHER_SPRITES[family]:
            raise ValueError(f"{family}: phase 0 drifted from the canonical static icon")
        if len(set(sequence)) < 2:
            raise ValueError(f"{family}: promoted animation is static")
        for phase, matrix in enumerate(sequence):
            if len(matrix) != MATRIX_CELLS or any(len(row) != MATRIX_CELLS for row in matrix):
                raise ValueError(f"{family} P{phase}: expected a 16x16 matrix")
            if matrix[-1] != "." * MATRIX_CELLS or any(row[-1] != "." for row in matrix):
                raise ValueError(f"{family} P{phase}: animation escaped the 15x15 drawable field")
            if set("".join(matrix)) - ({"."} | set(PALETTE)):
                raise ValueError(f"{family} P{phase}: unexpected palette symbol")
    if WEATHER_ANIMATION_FRAMES["clear_day"][:4] != WEATHER_ANIMATION_FRAMES["clear_day"][4:]:
        raise ValueError("clear_day: reviewed four-frame radial cycle no longer repeats")
    if _frameset_hash(WEATHER_ANIMATION_FRAMES) != PROMOTED_FRAMESET_SHA256:
        raise ValueError("promoted weather animation frameset hash drifted")


validate_weather_animation()


